/* csv-grid — the embeddable grid half of csv-viewer. Library entry.
 *
 *     import CsvGrid from 'csv-grid';            // or dist/csv-grid.es.js
 *     const grid = new CsvGrid(elementOrSelector, data, options);
 *
 * data (any one of, all with optional `name` for the status line and
 * optional `headerMode` overriding the construction option):
 *   { csv: string }                  parsed + inferred (worker if large)
 *   { records: [...], columns: [..] } array of objects (columns optional)
 *                                    or array of arrays (columns required);
 *                                    null/undefined/NaN cells become ''
 *   { url: string }                  fetched, then treated as csv
 *
 * options (defaults shown):
 *   globalSearch: true      fzf search box in a grid-generated toolbar
 *   columnFilters: true     per-column filter row
 *   sortable: true          click headers to sort
 *   statusBar: true         row-counts line (true = grid-generated,
 *                           an element = render into the host's element,
 *                           false = none)
 *   expandButtons: true     Expand / Contract pair in the toolbar
 *   align: null             'llrcr…' one of l/r/c per column, overrides
 *                           type defaults (rides the markdown col.align
 *                           plumbing); other characters = keep default
 *   formats: null           per-column format specs, null entry = auto
 *                           rules; subset of Python/d3: [,][.N](f|d|%|e|s)
 *                           plus the named 'year' and 'eng'
 *   widthMode: 'equal-risk' squeeze allocation when the table is wider
 *                           than its container: 'equal-risk' (every column
 *                           truncates with equal probability) or 'coverage'
 *                           (maximize the count of fully-shown cells)
 *   maxRows: null           cap the scroll viewport to ~N rows (vertical
 *                           scroll for the rest); null = unbounded
 *   height: null            raw CSS max-height for the scroll viewport
 *                           (e.g. '400px'); overrides maxRows when set
 *   renderCap: 2048         rows rendered before "show all" — only when the
 *                           scroll container is UNBOUNDED (the page scrolls);
 *                           a bounded scroller virtualizes instead (windowed
 *                           body, every row reachable). Also caps formatted export.
 *   eagerCells: 262144      below this, format + index everything at load
 *   worker: true            parse worker for csv >= ~1 MB; false = always
 *                           synchronous; or an explicit worker URL
 *   headerMode: 'auto'      'auto' | 'first-row' | 'headerless'
 *   displayMode: 'auto'     'auto' (type-aware formatting) | 'raw' (verbatim
 *                           source text); a view lens, no effect on export
 *   selectable: false       opt-in clickable rows/cells. false = today's
 *                           behavior exactly (no listener, no data-r, no
 *                           cursor). true = a body click dispatches a
 *                           bubbling, cancelable CustomEvent('csvgrid:cellclick')
 *                           from the grid root; event.detail carries the
 *                           clicked cell AND the whole row keyed by column
 *                           name (raw + formatted), with the ORIGINAL row
 *                           index (stable across sort/filter). The grid takes
 *                           no action beyond an optional selection highlight.
 *   selectMode: 'row'       'row' | 'cell' | 'none' — the visual highlight on
 *                           click ('none' still emits the event). An embedder
 *                           may preventDefault() the event to manage its own.
 *   hiddenColumns: null     string[] of header names kept in the data (so
 *                           they ride in the event payload + export) but not
 *                           rendered as visible columns; null = show all.
 *
 * event: 'csvgrid:cellclick' (when selectable) — see selectable above.
 *
 * methods: setData(data) -> Promise (a superseded load never settles;
 * failures reject AND show in the grid), destroy(),
 * export({scope, format, values}) -> string (CSV / markdown of the view or
 * whole table), setDisplayMode('auto'|'raw'), getSelection() / clearSelection()
 * / selectRow(rowIndex), and the static CsvGrid.forElement(elOrSelector) to
 * reach an instance built anonymously. The viewer app also drives its navbar
 * controls through setGlobalFilter / clearFilters / expand / contract /
 * setWidthMode / applyLayout.
 *
 * Multiple instances per page work: no module-global state, no element
 * ids, no document-level listeners (the transient drag-resize
 * mousemove/mouseup pair excepted). Data logic lives in core.js, pure
 * display logic in util.js, viewer chrome in src/app/app.js.
 */

import { cleanCsvText, processData } from './core.js';
import { parseFormatSpec, parseAlignSpec, formatCell, normalizeRecords,
         parseQuery, termScore, solveWidths, sampleIndices, makeColPredicate,
         makeSortKey, cellClass, escapeHtml, toCSV, toMarkdown, CELL_PAD, MIN_COL } from './util.js';

const WORKER_MIN_CHARS = 1000000; // ~1 MB; below this parse synchronously
const WIDTH_SAMPLE = 2048;        // rows sampled per column for width percentiles
const INDEX_CHUNK = 10000;        // rows per chunk when building the search index
const RENDER_BUFFER = 10;         // rows rendered above/below the viewport (windowed body)

function el(tag, cls) {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    return e;
}

export default class CsvGrid {
    constructor(target, data, options = {}) {
        const root = typeof target === 'string' ? document.querySelector(target) : target;
        if (!root) throw new Error('CsvGrid: target element not found.');
        this.root = root;
        root.csvgrid = this;     // instance handle on its own element (no ids, no globals)
        this.opts = {
            globalSearch: true, columnFilters: true, sortable: true,
            statusBar: true, expandButtons: true, align: null, formats: null,
            renderCap: 2048, eagerCells: 262144, worker: true,
            headerMode: 'auto', widthMode: 'equal-risk',
            maxRows: null, height: null, displayMode: 'auto',
            // opt-in clickable rows/cells (default off = today's behavior exactly)
            selectable: false, selectMode: 'row', hiddenColumns: null, ...options,
        };
        // 'auto' = type-aware formatting; 'raw' = verbatim source (the lens).
        // A view preference, independent of the export raw/formatted choice.
        this.displayMode = this.opts.displayMode === 'raw' ? 'raw' : 'auto';

        this.fileName = '';
        this.headers = [];
        this.rows = [];          // raw string cells
        this.cols = [];          // inference results, parallel to headers
        this.formatted = [];     // per-row display-string cache (lazy for large files)
        this.searchRaw = null;   // concatenated row text (formatted + raw) per row
        this.searchLow = null;   // lower-cased version, for case-insensitive terms
        this.searchReady = false;
        this.indexing = null;    // build progress 0..1 while chunking, else null
        this.loadGen = 0;        // bumped per load; abandons stale parses + index builds
        this.scores = [];        // fuzzy match score per row (current query)
        this.sortedOrder = null;  // all row indices in current sort order, filter-
                                  // independent; rebuilt only when the sort changes
                                  // so filtering never re-sorts (see rebuildView)
        this.layout = null;      // {arrays, floors} from measureLayout, frozen per load
        this.expandAll = false;  // bypass the squeeze: natural widths + h-scroll (sticky)
        this.manualWidths = new Map();   // col index -> px, set by drag-resize
        this.guessedHeaders = false;
        this.ambiguousDateCols = [];   // date cols defaulted to US m/d/y (see _install)
        this.view = [];          // row indices after filter + sort
        this.sortCol = null;
        this.sortDir = 1;
        this.globalFilter = '';
        this.colFilters = [];
        this.showAll = false;
        this.visibleCols = [];   // real column indices to render (hiddenColumns excluded)
        this.selected = null;    // {rowIndex, columnIndex} (original indices) when selectable
        // windowed (virtualized) body render — render only the on-screen slice
        // framed by two spacer rows; see renderBody. Geometry recomputed on
        // filter/sort/resize, the slice re-rendered on scroll.
        this._rowH = 0;          // measured data-row height (0 = not yet measured)
        this._winStart = 0;      // first view index currently in the DOM
        this._winEnd = 0;        // one past the last view index in the DOM
        this._windowed = false;  // true = virtualized slice; false = capped (unbounded container)
        this._scrollRaf = 0;     // pending rAF id coalescing scroll-driven re-windows

        this._worker = undefined;   // lazy; null = unavailable -> synchronous
        this._pending = new Map();  // load gen -> {resolve, reject} awaiting the worker

        this._buildScaffold();
        if (data) this.setData(data);
    }

    /* Generate the grid's own DOM inside the root: optional toolbar,
     * scrollable table, render-cap note, error line, status. */
    _buildScaffold() {
        const o = this.opts, root = this.root;
        root.classList.add('csvgrid');
        root.replaceChildren();
        this.els = {};
        if (o.globalSearch || o.expandButtons) {
            const tb = el('div', 'csvgrid-toolbar');
            if (o.globalSearch) {
                const inp = el('input', 'csvgrid-search');
                inp.type = 'text';
                inp.placeholder = "fzf search: term 'exact !not ^pre fix$";
                inp.title = "Space-separated terms AND together. Fuzzy by default; "
                    + "'exact, !exclude, ^prefix, suffix$. Uppercase = case-sensitive.";
                inp.addEventListener('input', () => this.setGlobalFilter(inp.value));
                inp.addEventListener('keydown', e => {
                    if (e.key === 'Escape') {
                        e.preventDefault();
                        inp.value = '';
                        inp.blur();
                        this.setGlobalFilter('');
                    }
                });
                tb.appendChild(inp);
                this.els.search = inp;
            }
            if (o.expandButtons) {
                // separate buttons by design — no mode-flipping toggles
                const ex = el('button', 'csvgrid-btn');
                ex.type = 'button';
                ex.textContent = 'Expand';
                ex.title = 'Expand all columns to their full natural width (table scrolls horizontally)';
                ex.addEventListener('click', () => this.expand());
                const ct = el('button', 'csvgrid-btn');
                ct.type = 'button';
                ct.textContent = 'Contract';
                ct.title = 'Back to fitted widths (equal-risk squeeze); also clears any dragged widths';
                ct.addEventListener('click', () => this.contract());
                tb.append(ex, ct);
            }
            root.appendChild(tb);
        }
        const wrap = el('div', 'csvgrid-scroll');
        // windowed render: re-slice on scroll (per-instance listener — complies
        // with the no document-level listeners rule). rAF-coalesced in _onScroll.
        wrap.addEventListener('scroll', () => this._onScroll());
        const table = el('table', 'csvgrid-table');
        const head = el('thead'), body = el('tbody');
        table.append(head, body);
        wrap.appendChild(table);
        root.appendChild(wrap);
        const capNote = el('div', 'csvgrid-capnote csvgrid-hidden');
        const showAllBtn = el('button', 'csvgrid-btn');
        showAllBtn.type = 'button';
        showAllBtn.addEventListener('click', () => {
            this.showAll = true;
            this.renderBody();
            this.renderStatus();
        });
        capNote.appendChild(showAllBtn);
        root.appendChild(capNote);
        const error = el('div', 'csvgrid-error csvgrid-hidden');
        root.appendChild(error);
        let status = null;
        if (o.statusBar === true) {
            status = el('div', 'csvgrid-status');
            root.appendChild(status);
        } else if (o.statusBar) {
            status = o.statusBar;       // host-supplied element
        }
        Object.assign(this.els, { table, head, body, scroll: wrap, capNote, showAllBtn, error, status });

        // tooltip with the full text, only for cells actually truncated
        table.addEventListener('mouseover', e => {
            const cell = e.target.closest('td, th');
            if (cell && !cell.title && cell.scrollWidth > cell.clientWidth) {
                cell.title = cell.textContent;
            }
        });

        // opt-in clickable rows/cells: ONE delegated listener on THIS
        // instance's own <tbody> (per-instance — complies with the no
        // document-level listeners rule). Off = no listener, no data-r,
        // no cursor: a true no-op.
        if (this.opts.selectable) {
            root.dataset.selectable = '';
            body.addEventListener('click', e => this._onBodyClick(e));
        }
    }

    // ------------------------------------------------------------ data in

    /* Resolve any data form, then install. Returns a promise; a load
     * superseded by a newer setData never settles (matches the old
     * stale-reply discard); a failed load rejects AND shows the error in
     * the grid. The rejection is pre-handled so embedders may ignore the
     * promise without unhandled-rejection noise. */
    setData(data) {
        const gen = ++this.loadGen;
        const ret = new Promise((resolve, reject) => {
            this._resolveData(data, gen).then(({ d, name }) => {
                if (gen !== this.loadGen) return;   // superseded
                this._install(d, name);
                resolve();
            }, err => {
                if (gen !== this.loadGen) return;
                this._showError(err.message || String(err));
                reject(err);
            });
        });
        ret.catch(() => {});
        return ret;
    }

    async _resolveData(data, gen) {
        if (!data || typeof data !== 'object') {
            throw new Error('CsvGrid: data must be {csv}, {records[, columns]}, or {url}.');
        }
        this._headerMode = data.headerMode ?? this.opts.headerMode;
        if (data.url !== undefined) {
            const url = String(data.url);
            const name = data.name ?? decodeURIComponent(url.split('/').pop() || url);
            const resp = await fetch(url);
            if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
            return { d: await this._parse(await resp.text(), gen, name), name };
        }
        if (data.csv !== undefined) {
            const name = data.name ?? '';
            return { d: await this._parse(data.csv, gen, name), name };
        }
        if (data.records !== undefined) {
            return { d: normalizeRecords(data.records, data.columns), name: data.name ?? '' };
        }
        throw new Error('CsvGrid: data must be {csv}, {records[, columns]}, or {url}.');
    }

    /* Synchronous processData below ~1 MB (or with worker:false); the
     * parse worker above, with progress in the status line. */
    _parse(text, gen, name) {
        text = cleanCsvText(text);
        if (!text.trim()) throw new Error('No data found.');
        const headerOverride = this._headerMode === 'first-row' ? true
            : this._headerMode === 'headerless' ? false : null;
        const w = (this.opts.worker !== false && text.length >= WORKER_MIN_CHARS)
            ? this._getWorker() : null;
        if (!w) return processData(text, headerOverride);
        this._setStatus(`parsing ${name || 'data'} (${(text.length / 1e6).toFixed(1)} MB)…`);
        return new Promise((resolve, reject) => {
            this._pending.set(gen, { resolve, reject });
            w.postMessage({ gen, text, headerOverride });
        });
    }

    /* Parse worker, created lazily; null = unavailable -> synchronous.
     * The `new Worker(new URL(...), {type:'module'})` literal is the
     * pattern both browsers (dev, served source) and Vite (dist bundles)
     * resolve: Vite compiles the worker into dist and rewrites the URL. */
    _getWorker() {
        if (this._worker === undefined) {
            this._worker = null;
            try {
                const w = typeof this.opts.worker === 'string'
                    ? new Worker(this.opts.worker)
                    : new Worker(new URL('./worker.js', import.meta.url), { type: 'module' });
                w.onmessage = e => {
                    const { gen, result, error } = e.data;
                    const pend = this._pending.get(gen);
                    if (!pend) return;          // stale reply
                    this._pending.delete(gen);
                    if (error) pend.reject(new Error(error));
                    else pend.resolve(result);
                };
                w.onerror = () => {
                    const all = [...this._pending.values()];
                    this._pending.clear();
                    for (const p of all) p.reject(new Error('Background parse failed.'));
                };
                this._worker = w;
            } catch { /* fall through to synchronous */ }
        }
        return this._worker;
    }

    /* Install a processData-shaped result and (re)render. Width
     * application no-ops while the root is hidden (clientWidth 0) — hosts
     * that reveal the grid afterwards call applyLayout() then. */
    _install(d, name) {
        const { rows, cols } = d;
        if (this.opts.align) {
            const spec = parseAlignSpec(this.opts.align);
            cols.forEach((col, c) => { if (spec[c]) col.align = spec[c]; });
        }
        if (this.opts.formats) {
            cols.forEach((col, c) => { col.fmt = parseFormatSpec(this.opts.formats[c]); });
        }
        this.fileName = name || '';
        this.guessedHeaders = d.headerless;
        // date columns whose all-numeric order was unknowable (defaulted to
        // US m/d/y) — the chrome surfaces this as a note; embedders may read it
        this.ambiguousDateCols = cols.filter(c => c.ambiguousOrder).map(c => c.name);
        this.headers = d.headers;
        this.rows = rows;
        this.cols = cols;
        // hiddenColumns (by header name) stay in the data — carried in the
        // click payload and export — but are excluded from the rendered
        // table. visibleCols is the identity list when none are hidden, so
        // every geometry path below reduces to its pre-feature behavior.
        const hide = Array.isArray(this.opts.hiddenColumns) && this.opts.hiddenColumns.length
            ? new Set(this.opts.hiddenColumns) : null;
        this.visibleCols = cols.map((_, c) => c).filter(c => !hide || !hide.has(this.headers[c]));
        this.selected = null;
        this.formatted = new Array(rows.length);
        this.searchRaw = null;
        this.searchLow = null;
        this.searchReady = false;
        this.indexing = null;
        if (rows.length * cols.length <= this.opts.eagerCells) {
            // small file: prefill everything, exactly the pre-2.0 behavior
            for (let r = 0; r < rows.length; r++) this.getFormattedRow(r);
            this.searchRaw = this.formatted.map(
                (frow, r) => frow.join(' ') + ' ' + rows[r].join(' '));
            this.searchLow = this.searchRaw.map(s => s.toLowerCase());
            this.searchReady = true;
        }
        this.sortCol = null;
        this.sortDir = 1;
        this.sortedOrder = null;   // rebuilt lazily by rebuildView for the new data
        this.globalFilter = '';
        this.colFilters = new Array(cols.length).fill('');
        this.manualWidths = new Map();
        this.showAll = false;
        // re-measure row height + reset the window for the new data
        this._rowH = 0;
        this._winStart = this._winEnd = 0;
        this._windowed = false;
        if (this.els.search) this.els.search.value = '';
        this.els.error.classList.add('csvgrid-hidden');
        this.renderHead();
        this.layout = this.measureLayout();   // frozen for this load
        this.applyLayout();
        this.refresh();
        this._applyHeight();
    }

    /* Bound the scroll viewport's height (vertical scroll for the rest,
     * sticky header stays). `height` is a raw CSS max-height; `maxRows`
     * caps it to ~N data rows, measured from the just-rendered table.
     * No-op (unbounded) when neither is set — the host may still cap it. */
    _applyHeight() {
        const o = this.opts;
        let bounded = false;
        if (o.height) {
            this.els.scroll.style.maxHeight = o.height;
            bounded = true;
        } else if (o.maxRows) {
            // measure a real data row (skip spacer rows of the windowed body)
            const dataRow = this.els.body.querySelector('tr:not(.csvgrid-spacer)');
            const rowH = this._rowH || (dataRow ? dataRow.offsetHeight : 0);
            if (rowH) {
                const headH = this.els.head.offsetHeight;
                this.els.scroll.style.maxHeight = Math.ceil(headH + rowH * o.maxRows + 2) + 'px';
                bounded = true;
            }
        }
        // capping the viewport changes clientHeight, so re-window against it
        if (bounded) this.renderBody();
    }

    _showError(msg) {
        this.els.error.textContent = msg;
        this.els.error.classList.remove('csvgrid-hidden');
    }

    _setStatus(text) {
        if (this.els.status) this.els.status.textContent = text;
    }

    destroy() {
        this.loadGen++;             // abandon pending parses and index builds
        this._pending.clear();
        if (this._scrollRaf) { cancelAnimationFrame(this._scrollRaf); this._scrollRaf = 0; }
        if (this._worker) { this._worker.terminate(); this._worker = null; }
        delete this.root.csvgrid;
        this.root.classList.remove('csvgrid');
        delete this.root.dataset.selectable;
        this.root.replaceChildren();
    }

    // ----------------------------------------------------- public controls

    setGlobalFilter(q) {
        this.globalFilter = q;
        this.refresh();
    }

    clearFilters() {
        this.globalFilter = '';
        this.colFilters = this.colFilters.map(() => '');
        if (this.els.search) this.els.search.value = '';
        this.renderHead();
        this.refresh();
    }

    expand() {
        this.expandAll = true;
        this.applyLayout();
    }

    contract() {
        this.expandAll = false;
        this.manualWidths.clear();
        this.applyLayout();
    }

    /* Serialize to a string for copy/save. Options:
     *   scope:  'view' (current filter + sort) | 'all' (every row, original
     *           file order, unfiltered — predictable, "minimum surprises")
     *   format: 'csv' (RFC 4180) | 'md' (markdown pipe table)
     *   values: 'raw' (cells as loaded) | 'formatted' (as displayed)
     * `formatted` is honored only when the chosen scope's row count is
     * within renderCap (formatting a quarter-million cells on a click would
     * stall); above that it transparently falls back to raw. Returns the
     * string; the caller decides the sink (clipboard / file) and any BOM. */
    export({ scope = 'view', format = 'csv', values = 'raw' } = {}) {
        const idx = scope === 'all'
            ? this.rows.map((_, i) => i)        // original order, unfiltered
            : this.view;                        // current filter + sort
        const formatted = values === 'formatted' && idx.length <= this.opts.renderCap;
        const rows2d = idx.map(r => formatted
            ? this.getFormattedRow(r)
            : this.cols.map((_, c) => this.rows[r][c] ?? ''));
        if (format === 'md') {
            const aligns = this.cols.map(col => col.align
                || (col.type === 'number' ? 'right' : col.type === 'date' ? 'center' : 'left'));
            return toMarkdown(this.headers, rows2d, aligns);
        }
        return toCSV(this.headers, rows2d);
    }

    /* Switch the squeeze allocation method and re-solve. Same measured
     * layout, no reload — only the budget allocation changes. */
    setWidthMode(mode) {
        this.opts.widthMode = mode === 'coverage' ? 'coverage' : 'equal-risk';
        this.applyLayout();
    }

    /* Switch the display lens between 'auto' (type-aware formatting) and
     * 'raw' (verbatim source). No re-parse — reuses this.rows/this.cols;
     * drops the formatted + search caches (both derive from display text),
     * re-measures widths (raw text differs in length), and re-renders.
     * Independent of the export raw/formatted option. */
    setDisplayMode(mode) {
        mode = mode === 'raw' ? 'raw' : 'auto';
        if (mode === this.displayMode || !this.cols.length) { this.displayMode = mode; return; }
        this.displayMode = mode;
        this.formatted = new Array(this.rows.length);   // re-derive on demand
        this.searchRaw = null;
        this.searchLow = null;
        this.searchReady = false;
        this.indexing = null;
        if (this.rows.length * this.cols.length <= this.opts.eagerCells) {
            for (let r = 0; r < this.rows.length; r++) this.getFormattedRow(r);
            this.searchRaw = this.formatted.map(
                (frow, r) => frow.join(' ') + ' ' + this.rows[r].join(' '));
            this.searchLow = this.searchRaw.map(s => s.toLowerCase());
            this.searchReady = true;
        }
        this.layout = this.measureLayout();   // widths re-freeze for this lens
        this.applyLayout();
        this.refresh();
    }

    // ------------------------------------------------------------- layout

    /* Measure formatted cell and header widths with a canvas in the table's
     * font. Returns {arrays, floors}: per-column sorted cell widths and
     * minimum (header-driven) widths. */
    measureLayout() {
        // one scratch canvas shared by all instances
        const canvas = CsvGrid._canvas || (CsvGrid._canvas = document.createElement('canvas'));
        const ctx = canvas.getContext('2d');
        const cs = getComputedStyle(this.els.table);
        const font = `${cs.fontSize} ${cs.fontFamily}`;
        // sampled, not exhaustive: quantiles from ~2K rows per column (2.0.0)
        const sample = sampleIndices(this.rows.length, WIDTH_SAMPLE);
        const arrays = [], floors = [];
        // arrays/floors are indexed by VISIBLE position (parallel to the
        // rendered colgroup); hidden columns are skipped entirely.
        for (const c of this.visibleCols) {
            ctx.font = `bold ${font}`;
            // 14px ≈ the sort-arrow slot in the header
            floors.push(Math.max(MIN_COL,
                Math.ceil(ctx.measureText(this.cols[c].name).width) + 14 + CELL_PAD));
            ctx.font = font;
            const w = [];
            for (const r of sample) {
                const text = this.getFormattedRow(r)[c];
                if (text !== '') w.push(Math.ceil(ctx.measureText(text).width) + CELL_PAD);
            }
            w.sort((a, b) => a - b);
            arrays.push(w);
        }
        return { arrays, floors };
    }

    /* Drag-resize: a handle on each header's right edge. Drag sets a manual
     * width override (kept across re-solves until the next file load);
     * double-click fits the column to its content (Excel-style). `p` is the
     * VISIBLE column position (= the colgroup / layout index, which excludes
     * hidden columns); manualWidths is keyed the same way. */
    startColResize(e, p) {
        e.preventDefault();
        e.stopPropagation();
        const table = this.els.table;
        const col = table.querySelectorAll('colgroup col')[p];
        if (!col) return;
        const startX = e.clientX;
        const startW = parseFloat(col.style.width);
        document.body.classList.add('csvgrid-resizing');
        const setTableWidth = () => {
            let sum = 0;
            table.querySelectorAll('colgroup col').forEach(k => { sum += parseFloat(k.style.width); });
            table.style.width = sum + 'px';
        };
        const move = ev => {
            const w = Math.max(24, Math.round(startW + ev.clientX - startX));
            this.manualWidths.set(p, w);
            col.style.width = w + 'px';
            setTableWidth();
        };
        const up = () => {
            document.body.classList.remove('csvgrid-resizing');
            document.removeEventListener('mousemove', move);
            document.removeEventListener('mouseup', up);
        };
        document.addEventListener('mousemove', move);
        document.addEventListener('mouseup', up);
    }

    fitColumn(p) {   // p = visible column position (layout / colgroup index)
        const { arrays, floors } = this.layout;
        const natural = Math.max(floors[p], arrays[p].length ? arrays[p][arrays[p].length - 1] : 0);
        this.manualWidths.set(p, natural);
        this.applyLayout();
    }

    /* Solve against the current viewport and pin widths via <colgroup> +
     * table-layout: fixed. */
    applyLayout() {
        if (!this.layout) return;
        const table = this.els.table;
        const avail = this.expandAll ? Infinity : table.parentElement.clientWidth;
        if (!avail) return;
        const widths = solveWidths(this.layout.arrays, this.layout.floors, avail, this.opts.widthMode);
        for (const [c, w] of this.manualWidths) if (c < widths.length) widths[c] = w;
        let cg = table.querySelector('colgroup');
        if (cg) cg.remove();
        cg = document.createElement('colgroup');
        for (const w of widths) {
            const col = document.createElement('col');
            col.style.width = w + 'px';
            cg.appendChild(col);
        }
        table.prepend(cg);
        table.style.tableLayout = 'fixed';
        table.style.width = widths.reduce((a, b) => a + b, 0) + 'px';
        // The viewport may have just become visible (the app reveals the table
        // AFTER setData, then calls applyLayout) or changed size (resize /
        // expand). Re-window against the now-known geometry. Skipped before the
        // first render (the during-_install call has no view yet) to avoid churn.
        if (this.view.length) this.renderBody();
    }

    // ----------------------------------------------- lazy format / index

    /* Format a row on demand and cache it. Small files are prefilled at
     * load; large files only ever format what rendering, width-sampling, or
     * the search index actually touch. */
    getFormattedRow(r) {
        let f = this.formatted[r];
        if (!f) {
            f = this.cols.map((col, c) => formatCell(this.rows[r][c], col, r, this.displayMode));
            this.formatted[r] = f;
        }
        return f;
    }

    /* Build the global-search index (formatted + raw text per row) in
     * chunks, yielding to the UI between chunks; progress shows in the
     * status line. The pending query applies automatically on completion. A
     * stale build is abandoned if a new file loads (loadGen). */
    buildSearchIndexChunked() {
        const gen = this.loadGen;
        const n = this.rows.length;
        const raw = new Array(n), low = new Array(n);
        let r = 0;
        this.indexing = 0;
        const step = () => {
            if (gen !== this.loadGen) return;   // a new file arrived; abandon
            const end = Math.min(n, r + INDEX_CHUNK);
            for (; r < end; r++) {
                const s = this.getFormattedRow(r).join(' ') + ' ' + this.rows[r].join(' ');
                raw[r] = s;
                low[r] = s.toLowerCase();
            }
            if (r < n) {
                this.indexing = r / n;
                this.renderStatus();
                setTimeout(step, 0);
            } else {
                this.searchRaw = raw;
                this.searchLow = low;
                this.searchReady = true;
                this.indexing = null;
                this.refresh();
            }
        };
        step();
    }

    // ------------------------------------------------------ filter + sort

    /* Build sortedOrder: every row index in the current column-sort order,
     * filter-independent. Done ONCE per sort change (onSort / new data), so
     * filtering — which preserves order — never re-sorts. sortCol === null is
     * the identity (original file order). Text columns sort by a precomputed
     * natural-order key (primitive compares, no per-pair Intl.Collator); blanks
     * last regardless of direction, exactly as the old collator path. */
    _buildSortOrder() {
        const n = this.rows.length;
        const order = new Array(n);
        for (let i = 0; i < n; i++) order[i] = i;
        const sc = this.sortCol;
        if (sc !== null) {
            const col = this.cols[sc], dir = this.sortDir;
            if (col.type === 'text') {
                const keys = new Array(n);
                for (let i = 0; i < n; i++) keys[i] = makeSortKey(this.rows[i][sc]);
                order.sort((a, b) => {
                    const x = keys[a], y = keys[b];
                    if (x === '' || y === '') return x === y ? 0 : (x === '' ? 1 : -1);
                    return x < y ? -dir : x > y ? dir : 0;
                });
            } else {
                const v = col.values;
                order.sort((a, b) => {
                    const x = v[a], y = v[b];
                    if (x === null || y === null) return x === y ? 0 : (x === null ? 1 : -1);
                    return dir * (x - y);
                });
            }
        }
        this.sortedOrder = order;
    }

    rebuildView() {
        const { rows, cols } = this;
        let terms = parseQuery(this.globalFilter);
        // global search needs the index; kick off the chunked build and leave
        // the global term unapplied until it lands (column filters work now)
        if (terms.length && !this.searchReady) {
            if (this.indexing === null) this.buildSearchIndexChunked();
            terms = [];
        }
        const hasFuzzy = terms.some(t => t.kind === 'fuzzy' && !t.negate);
        const preds = this.colFilters.map((f, c) => makeColPredicate(f || '', cols[c]));
        const active = preds.some(p => p) || terms.length;
        // fuzzy match scores only matter for relevance ranking — i.e. when there
        // is NO explicit column sort; otherwise we skip scoring entirely.
        const rank = hasFuzzy && this.sortCol === null;

        if (!this.sortedOrder || this.sortedOrder.length !== rows.length) this._buildSortOrder();
        const order = this.sortedOrder;

        // No filter: the whole sorted order IS the view (sliced so callers can't
        // mutate the cached order). This is the common refresh after a sort.
        if (!active) { this.view = order.slice(); return; }

        // Filter in sorted order — the survivors stay sorted, so there is no
        // per-keystroke re-sort (the win). Relevance ranking is the one case
        // that still sorts, and only over the matched subset.
        const idx = [];
        if (rank) this.scores = [];
        for (let oi = 0; oi < order.length; oi++) {
            const r = order[oi];
            let ok = true, score = 0;
            for (const t of terms) {
                const s = termScore(t, this.searchLow[r], this.searchRaw[r]);
                if (s < 0) { ok = false; break; }
                score += s;
            }
            if (ok) {
                for (let c = 0; c < preds.length; c++) {
                    if (preds[c] && !preds[c]((rows[r][c] ?? ''), r)) { ok = false; break; }
                }
            }
            if (!ok) continue;
            if (rank) this.scores[r] = score;
            idx.push(r);
        }
        if (rank) idx.sort((a, b) => (this.scores[b] - this.scores[a]) || (a - b));
        this.view = idx;
    }

    // ---------------------------------------------------------- rendering

    renderHead() {
        const { cols } = this;
        const head = this.els.head;
        head.innerHTML = '';

        // iterate VISIBLE columns; c = real column index (sort/filter engine
        // stays on real indices), p = visible position (colgroup / width
        // geometry). Identical to a plain cols.forEach when nothing is hidden.
        const hr = document.createElement('tr');
        this.visibleCols.forEach((c, p) => {
            const col = cols[c];
            const th = document.createElement('th');
            th.className = cellClass(col);
            if (this.opts.sortable) {
                const arrow = this.sortCol === c ? (this.sortDir === 1 ? '▲' : '▼') : '';
                th.innerHTML = `<span class="sort-arrow">${arrow}</span>${escapeHtml(col.name)}`;
                th.title = `${col.name} (${col.type}) — click to sort`;
                th.addEventListener('click', () => this.onSort(c));
            } else {
                th.innerHTML = `<span class="sort-arrow"></span>${escapeHtml(col.name)}`;
                th.title = `${col.name} (${col.type})`;
                th.classList.add('csvgrid-nosort');
            }
            const grip = document.createElement('span');
            grip.className = 'col-resizer';
            grip.title = 'Drag to resize — double-click to fit content';
            grip.addEventListener('mousedown', e => this.startColResize(e, p));
            grip.addEventListener('dblclick', e => { e.stopPropagation(); this.fitColumn(p); });
            grip.addEventListener('click', e => e.stopPropagation());
            th.appendChild(grip);
            hr.appendChild(th);
        });
        head.appendChild(hr);

        if (!this.opts.columnFilters) return;
        const fr = document.createElement('tr');
        fr.className = 'filter-row';
        this.visibleCols.forEach((c) => {
            const col = cols[c];
            const th = document.createElement('th');
            const inp = document.createElement('input');
            inp.type = 'text';
            inp.className = 'csvgrid-filter';
            inp.placeholder = col.type === 'text' ? 'filter' : 'filter, >, .. ';
            inp.value = this.colFilters[c] || '';
            inp.addEventListener('input', () => {
                this.colFilters[c] = inp.value;
                inp.classList.toggle('active-filter', inp.value.trim() !== '');
                this.refresh();
            });
            inp.addEventListener('keydown', e => {
                if (e.key === 'Escape') {
                    e.preventDefault();
                    inp.value = '';
                    this.colFilters[c] = '';
                    inp.classList.remove('active-filter');
                    inp.blur();
                    this.refresh();
                }
            });
            th.appendChild(inp);
            fr.appendChild(th);
        });
        head.appendChild(fr);
    }

    /* (Re)build the body for the current view. Windowed: only the rows in the
     * scroll viewport (+ a buffer) are in the DOM, framed by two zero-content
     * spacer rows that reserve the off-screen height so the scrollbar and the
     * sticky header behave. Cost is O(viewport), independent of view.length.
     *
     * Windowing needs a bounded scroller (one that clips + scrolls internally).
     * When the container is unbounded (the default embed — the page scrolls,
     * not the container — so scrollTop never moves), we fall back to today's
     * renderCap + "show all" path so there's no blank gap. */
    renderBody() {
        const { view } = this;
        const body = this.els.body, scroll = this.els.scroll;
        if (!view.length) {
            body.innerHTML = '';
            this._winStart = this._winEnd = 0;
            this._windowed = false;
            this._updateCapNote();
            return;
        }
        // Row height drives the geometry; measure it once from a real data row.
        // Needs a visible DOM (offsetHeight is 0 while hidden) — the app loads
        // with the table hidden and reveals it afterwards via applyLayout(),
        // which re-enters here. Until then, render the capped set as a safe
        // fallback (matches pre-3.7 behavior for any never-revealed embed).
        if (!this._rowH) {
            this._renderSlice(0, Math.min(view.length, 60), 0, 0);   // probe
            const tr = body.querySelector('tr:not(.csvgrid-spacer)');
            this._rowH = tr ? tr.offsetHeight : 0;
            if (!this._rowH) {
                const cap = Math.min(view.length, this.opts.renderCap);
                this._renderSlice(0, cap, 0, 0);
                this._winStart = 0; this._winEnd = cap; this._windowed = false;
                this._updateCapNote();
                return;
            }
        }
        const h = this._rowH;
        const win = this._computeWindow();
        this._renderSlice(win.start, win.end, win.start * h, (view.length - win.end) * h);
        // Does the container actually clip? The spacers now reserve the full
        // height, so a bounded scroller has clientHeight < scrollHeight.
        if (scroll.scrollHeight - scroll.clientHeight > 1) {
            this._windowed = true;
            this._winStart = win.start; this._winEnd = win.end;
        } else {
            // unbounded: windowing can't engage. Render up to the cap (or all,
            // if the user pressed "show all"); no spacers.
            this._windowed = false;
            const cap = this.showAll ? view.length : Math.min(view.length, this.opts.renderCap);
            this._renderSlice(0, cap, 0, 0);
            this._winStart = 0; this._winEnd = cap;
        }
        this._updateCapNote();
    }

    /* Render view[start, end) into <tbody>, framed by top/bottom spacer rows of
     * `topH`/`botH` px (0 = omitted). The spacer's td spans every visible
     * column so the table's horizontal extent is preserved when the slice is
     * sparse. data-r (original row index) rides only on real data rows. */
    _renderSlice(start, end, topH, botH) {
        const { cols, view } = this;
        const sel = this.opts.selectable;
        const ncol = this.visibleCols.length;
        const parts = [];
        if (topH > 0) parts.push(`<tr class="csvgrid-spacer"><td colspan="${ncol}" style="height:${topH}px"></td></tr>`);
        for (let i = start; i < end; i++) {
            const r = view[i];
            const frow = this.getFormattedRow(r);
            const cells = this.visibleCols.map(c => {
                const col = cols[c];
                const text = frow[c];
                if (text === '') return `<td class="${cellClass(col)} blank">·</td>`;
                return `<td class="${cellClass(col)}">${escapeHtml(text)}</td>`;
            });
            parts.push(`<tr${sel ? ` data-r="${r}"` : ''}>${cells.join('')}</tr>`);
        }
        if (botH > 0) parts.push(`<tr class="csvgrid-spacer"><td colspan="${ncol}" style="height:${botH}px"></td></tr>`);
        this.els.body.innerHTML = parts.join('');
        if (sel) this._paintSelection();   // selection survives the re-render
    }

    /* The [start, end) view slice that covers the current scroll viewport plus
     * a buffer above and below. */
    _computeWindow() {
        const { view, _rowH: h } = this;
        const scroll = this.els.scroll;
        const total = view.length;
        const vh = scroll.clientHeight || (total * h);
        const visible = Math.max(1, Math.ceil(vh / h));
        const start = Math.max(0, Math.floor(scroll.scrollTop / h) - RENDER_BUFFER);
        const end = Math.min(total, start + visible + 2 * RENDER_BUFFER);
        return { start, end };
    }

    /* Scroll-driven re-slice: rAF-coalesced (one render per frame on a fling),
     * and a no-op when the window hasn't moved by a whole row. Inert unless the
     * body is actually windowed (the capped fallback has every row in the DOM). */
    _onScroll() {
        if (!this._windowed || this._scrollRaf) return;
        this._scrollRaf = requestAnimationFrame(() => {
            this._scrollRaf = 0;
            if (!this._windowed) return;
            const { start, end } = this._computeWindow();
            if (start === this._winStart && end === this._winEnd) return;
            this._winStart = start; this._winEnd = end;
            this._renderSlice(start, end, start * this._rowH, (this.view.length - end) * this._rowH);
        });
    }

    /* The "showing first N — show all" note: only meaningful in the capped
     * (unbounded-container) fallback. When windowed, every row is reachable by
     * scrolling, so the note stays hidden. */
    _updateCapNote() {
        const note = this.els.capNote;
        if (!note) return;
        const total = this.view.length;
        if (!this._windowed && this._winEnd < total) {
            note.classList.remove('csvgrid-hidden');
            this.els.showAllBtn.textContent =
                `Showing first ${this._winEnd.toLocaleString()} of ${total.toLocaleString()} rows — show all`;
        } else {
            note.classList.add('csvgrid-hidden');
        }
    }

    renderStatus() {
        if (!this.els.status) return;
        const fmt = n => n.toLocaleString();
        const total = this.rows.length;
        const shown = this.view.length;
        let s = this.fileName ? this.fileName + ' — ' : '';
        s += shown === total ? `${fmt(total)} rows` : `${fmt(shown)} of ${fmt(total)} rows`;
        s += ` × ${this.cols.length} cols`;
        // windowed: every row is scroll-reachable; only the capped fallback
        // (unbounded container) limits what's rendered, and says so.
        if (!this._windowed && this._winEnd < shown) s += ` — showing rows 1–${fmt(this._winEnd)}`;
        if (this.guessedHeaders) s += ' (headers guessed)';
        if (this.indexing !== null) s += ` — indexing search ${Math.round(this.indexing * 100)}%`;
        this.els.status.textContent = s;
    }

    refresh() {
        this.rebuildView();
        this.renderBody();
        this.renderStatus();
    }

    // -------------------------------------------------------------- events

    onSort(c) {
        if (this.sortCol === c) {
            if (this.sortDir === 1) this.sortDir = -1;
            else { this.sortCol = null; this.sortDir = 1; }   // third click: reset
        } else {
            this.sortCol = c; this.sortDir = 1;
        }
        this._buildSortOrder();   // the only place the order actually changes
        this.renderHead();
        this.refresh();
    }

    // ------------------------------------------------- selection / click

    /* Find the CsvGrid instance on a root element (or selector), or null —
     * the documented way to reach a grid that to_html/show built anonymously
     * (also `event.target.closest('.csvgrid').csvgrid`). */
    static forElement(elOrSelector) {
        const el = typeof elOrSelector === 'string'
            ? document.querySelector(elOrSelector) : elOrSelector;
        return el ? (el.csvgrid || null) : null;
    }

    /* The clicked cell's value: the typed number where the grid has one
     * (so consumers get a number, not "$1,234"), else the raw source string,
     * else null for a blank. */
    _rawValue(r, c) {
        const col = this.cols[c];
        if (col && col.type === 'number') {
            const v = col.values[r];
            if (v !== null && v !== undefined) return v;
        }
        return this.rows[r][c] ?? null;
    }

    /* Build the event/selection detail for original row r, clicked column c.
     * `row`/`rowText` cover EVERY column by name — including hiddenColumns —
     * so identity travels in the payload and survives sort/filter. */
    _rowDetail(r, c, originalEvent) {
        const frow = this.getFormattedRow(r);
        const row = {}, rowText = {};
        this.headers.forEach((h, i) => {
            row[h] = this._rawValue(r, i);
            rowText[h] = frow[i] ?? '';
        });
        return {
            name: this.fileName,
            rowIndex: r,
            viewIndex: this.view.indexOf(r),
            column: this.headers[c],
            columnIndex: c,
            value: this._rawValue(r, c),
            valueText: frow[c] ?? '',
            row, rowText, originalEvent,
        };
    }

    _onBodyClick(e) {
        const td = e.target.closest('td');
        const tr = td && td.parentElement;
        if (!td || !tr || tr.dataset.r === undefined) return;
        const r = +tr.dataset.r;                          // original row index
        const p = [...tr.children].indexOf(td);           // visible position
        const c = this.visibleCols[p];                    // real column index
        if (c === undefined) return;
        const ev = new CustomEvent('csvgrid:cellclick',
            { detail: this._rowDetail(r, c, e), bubbles: true, composed: true, cancelable: true });
        // dispatch first; an embedder may preventDefault() to manage its own
        // highlight, in which case we skip the built-in selection.
        const proceed = this.root.dispatchEvent(ev);
        if (proceed && this.opts.selectMode !== 'none') {
            this.selected = { rowIndex: r, columnIndex: c };
            this._paintSelection();
        }
    }

    /* Re-apply the selection highlight to the current DOM (called after every
     * renderBody so selection survives sort/filter/expand). Cheap no-op when
     * nothing is selected or the selected row isn't currently rendered. */
    _paintSelection() {
        const body = this.els.body;
        body.querySelectorAll('.csvgrid-selected, .csvgrid-selected-row')
            .forEach(el => el.classList.remove('csvgrid-selected', 'csvgrid-selected-row'));
        if (!this.selected || this.opts.selectMode === 'none') return;
        const tr = body.querySelector(`tr[data-r="${this.selected.rowIndex}"]`);
        if (!tr) return;
        if (this.opts.selectMode === 'cell') {
            tr.classList.add('csvgrid-selected-row');
            const td = tr.children[this.visibleCols.indexOf(this.selected.columnIndex)];
            if (td) td.classList.add('csvgrid-selected');
        } else {
            tr.classList.add('csvgrid-selected');
        }
    }

    /* The current selection in the same shape as the event detail, or null. */
    getSelection() {
        if (!this.selected) return null;
        return this._rowDetail(this.selected.rowIndex, this.selected.columnIndex, null);
    }

    clearSelection() {
        this.selected = null;
        if (this.opts.selectable) this._paintSelection();
    }

    /* Programmatically select an original row index and scroll it into view —
     * e.g. to mirror the row a detail panel is showing. No-op if the row is
     * filtered out of the current view. */
    selectRow(rowIndex) {
        if (!this.opts.selectable) return;
        this.selected = { rowIndex, columnIndex: this.selected ? this.selected.columnIndex : this.visibleCols[0] };
        const vi = this.view.indexOf(rowIndex);   // position in the current view
        if (vi < 0) { this._paintSelection(); return; }   // filtered out of the view
        if (this._windowed && this._rowH) {
            // the target row may be outside the rendered window: scroll by its
            // computed offset, then re-window so its <tr> exists to paint.
            const h = this._rowH, scroll = this.els.scroll;
            const top = vi * h;
            if (top < scroll.scrollTop || top + h > scroll.scrollTop + scroll.clientHeight) {
                scroll.scrollTop = Math.max(0, top - h * RENDER_BUFFER);
            }
            this.renderBody();   // re-slices at the new offset and repaints
            return;
        }
        this._paintSelection();
        const tr = this.els.body.querySelector(`tr[data-r="${rowIndex}"]`);
        if (tr) tr.scrollIntoView({ block: 'nearest' });
    }
}
